def orient_set(shp):
 pts=list(shp); forms=set()
 for flip in [1,-1]:
  for rot in range(4):
   q=[]
   for r,c in pts:
    x,y=r,flip*c
    for _ in range(rot): x,y=y,-x
    q.append((x,y))
   mr=min(x for x,y in q); mc=min(y for x,y in q)
   forms.add(tuple(sorted((x-mr,y-mc) for x,y in q)))
 return forms
